INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000001,'quizzes','{"id":760200000000001,"title":"A1 · Разговорный · Знакомство и этикет · Quiz 1","description":"A1: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A1","icon":"📝","xp":23,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"5 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «thank you».","options":["пожалуйста","спасибо","увидимся позже","привет"],"correctAnswer":"спасибо","explanation":"«thank you» — «спасибо»."},{"id":2,"question":"Какое выражение на британском английском соответствует «увидимся позже»?","options":["hello","how are you?","good evening","see you later"],"correctAnswer":"see you later","explanation":"«see you later» — «увидимся позже»."},{"id":3,"question":"Выбери точное русское значение выражения «could you help me?».","options":["добрый вечер","как дела?","не могли бы вы мне помочь?","извините"],"correctAnswer":"не могли бы вы мне помочь?","explanation":"«could you help me?» — «не могли бы вы мне помочь?»."},{"id":4,"question":"Выбери точное русское значение выражения «nice to meet you».","options":["привет","добрый вечер","приятно познакомиться","мне жаль"],"correctAnswer":"приятно познакомиться","explanation":"«nice to meet you» — «приятно познакомиться»."},{"id":5,"question":"Какое выражение на британском английском соответствует «мне жаль»?","options":["thank you","I am sorry","good evening","hello"],"correctAnswer":"I am sorry","explanation":"«I am sorry» — «мне жаль»."},{"id":6,"question":"Выбери точное русское значение выражения «good morning».","options":["не могли бы вы мне помочь?","приятно познакомиться","пожалуйста","доброе утро"],"correctAnswer":"доброе утро","explanation":"«good morning» — «доброе утро»."},{"id":7,"question":"Выбери точное русское значение выражения «hello».","options":["приятно познакомиться","привет","увидимся позже","не могли бы вы мне помочь?"],"correctAnswer":"привет","explanation":"«hello» — «привет»."},{"id":8,"question":"Какое выражение на британском английском соответствует «пожалуйста»?","options":["thank you","I am sorry","please","nice to meet you"],"correctAnswer":"please","explanation":"«please» — «пожалуйста»."}],"durationMinutes":5}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000002,'quizzes','{"id":760200000000002,"title":"A2 · Разговорный · Знакомство и этикет · Quiz 2","description":"A2: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"📝","xp":25,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"6 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «by the way».","options":["дай мне знать","это зависит от обстоятельств","я не согласен","кстати"],"correctAnswer":"кстати","explanation":"«by the way» — «кстати»."},{"id":2,"question":"Какое выражение на британском английском соответствует «это зависит от обстоятельств»?","options":["let me know","I am not sure","it depends","by the way"],"correctAnswer":"it depends","explanation":"«it depends» — «это зависит от обстоятельств»."},{"id":3,"question":"Выбери точное русское значение выражения «I agree».","options":["можно мне","я согласен","кстати","дай мне знать"],"correctAnswer":"я согласен","explanation":"«I agree» — «я согласен»."},{"id":4,"question":"Выбери точное русское значение выражения «shall we start?».","options":["я согласен","начнём?","кстати","я не уверен"],"correctAnswer":"начнём?","explanation":"«shall we start?» — «начнём?»."},{"id":5,"question":"Какое выражение на британском английском соответствует «дай мне знать»?","options":["let me know","shall we start?","could I have","I disagree"],"correctAnswer":"let me know","explanation":"«let me know» — «дай мне знать»."},{"id":6,"question":"Выбери точное русское значение выражения «take your time».","options":["дай мне знать","кстати","что ты думаешь?","не торопись"],"correctAnswer":"не торопись","explanation":"«take your time» — «не торопись»."},{"id":7,"question":"Выбери точное русское значение выражения «I would like».","options":["кстати","я согласен","я бы хотел","я ищу"],"correctAnswer":"я бы хотел","explanation":"«I would like» — «я бы хотел»."},{"id":8,"question":"Какое выражение на британском английском соответствует «я не согласен»?","options":["by the way","take your time","could I have","I disagree"],"correctAnswer":"I disagree","explanation":"«I disagree» — «я не согласен»."}],"durationMinutes":6}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000003,'quizzes','{"id":760200000000003,"title":"B1 · Разговорный · Знакомство и этикет · Quiz 3","description":"B1: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"📝","xp":30,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"7 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «clear up a misunderstanding».","options":["прояснить недоразумение","по моему мнению","я понимаю твою точку зрения","с другой стороны"],"correctAnswer":"прояснить недоразумение","explanation":"«clear up a misunderstanding» — «прояснить недоразумение»."},{"id":2,"question":"Какое выражение на британском английском соответствует «если честно»?","options":["that sounds reasonable","to be honest","on the other hand","reach an agreement"],"correctAnswer":"to be honest","explanation":"«to be honest» — «если честно»."},{"id":3,"question":"Выбери точное русское значение выражения «as far as I know».","options":["с другой стороны","насколько мне известно","с нетерпением ждать","принимать участие в"],"correctAnswer":"насколько мне известно","explanation":"«as far as I know» — «насколько мне известно»."},{"id":4,"question":"Выбери точное русское значение выражения «in my opinion».","options":["принимать участие в","насколько мне известно","это звучит разумно","по моему мнению"],"correctAnswer":"по моему мнению","explanation":"«in my opinion» — «по моему мнению»."},{"id":5,"question":"Какое выражение на британском английском соответствует «с другой стороны»?","options":["as far as I know","on the other hand","in my opinion","keep in touch"],"correctAnswer":"on the other hand","explanation":"«on the other hand» — «с другой стороны»."},{"id":6,"question":"Выбери точное русское значение выражения «take part in».","options":["с нетерпением ждать","я понимаю твою точку зрения","принимать участие в","предложить идею"],"correctAnswer":"принимать участие в","explanation":"«take part in» — «принимать участие в»."},{"id":7,"question":"Выбери точное русское значение выражения «look forward to».","options":["это звучит разумно","достичь соглашения","с нетерпением ждать","поддерживать связь"],"correctAnswer":"с нетерпением ждать","explanation":"«look forward to» — «с нетерпением ждать»."},{"id":8,"question":"Какое выражение на британском английском соответствует «это звучит разумно»?","options":["make a suggestion","that sounds reasonable","on the other hand","I see your point"],"correctAnswer":"that sounds reasonable","explanation":"«that sounds reasonable» — «это звучит разумно»."}],"durationMinutes":7}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000004,'quizzes','{"id":760200000000004,"title":"B2 · Разговорный · Знакомство и этикет · Quiz 4","description":"B2: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"📝","xp":35,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"8 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «put it another way».","options":["выразить сомнение","принять во внимание","выразить иначе","взвесить варианты"],"correctAnswer":"выразить иначе","explanation":"«put it another way» — «выразить иначе»."},{"id":2,"question":"Какое выражение на британском английском соответствует «ответить тактично»?","options":["express a reservation","make a valid point","strike a balance","respond tactfully"],"correctAnswer":"respond tactfully","explanation":"«respond tactfully» — «ответить тактично»."},{"id":3,"question":"Выбери точное русское значение выражения «weigh up the options».","options":["прояснить предположение","взвесить варианты","выразить обеспокоенность","выразить иначе"],"correctAnswer":"взвесить варианты","explanation":"«weigh up the options» — «взвесить варианты»."},{"id":4,"question":"Выбери точное русское значение выражения «take into account».","options":["принять во внимание","прийти к выводу","разобраться с недопониманием","испытывать смешанные чувства"],"correctAnswer":"принять во внимание","explanation":"«take into account» — «принять во внимание»."},{"id":5,"question":"Какое выражение на британском английском соответствует «выразить обеспокоенность»?","options":["have mixed feelings","raise a concern","put it another way","weigh up the options"],"correctAnswer":"raise a concern","explanation":"«raise a concern» — «выразить обеспокоенность»."},{"id":6,"question":"Выбери точное русское значение выражения «come to a conclusion».","options":["принять во внимание","выразить иначе","взвесить варианты","прийти к выводу"],"correctAnswer":"прийти к выводу","explanation":"«come to a conclusion» — «прийти к выводу»."},{"id":7,"question":"Выбери точное русское значение выражения «address a misunderstanding».","options":["взвесить варианты","выразить обеспокоенность","найти баланс","разобраться с недопониманием"],"correctAnswer":"разобраться с недопониманием","explanation":"«address a misunderstanding» — «разобраться с недопониманием»."},{"id":8,"question":"Какое выражение на британском английском соответствует «выразить сомнение»?","options":["raise a concern","strike a balance","have mixed feelings","express a reservation"],"correctAnswer":"express a reservation","explanation":"«express a reservation» — «выразить сомнение»."}],"durationMinutes":8}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000005,'quizzes','{"id":760200000000005,"title":"C1 · Разговорный · Знакомство и этикет · Quiz 5","description":"C1: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":40,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «elaborate on a point».","options":["выражаться точно","развернуть мысль","уточнить оговорками утверждение","найти точки соприкосновения"],"correctAnswer":"развернуть мысль","explanation":"«elaborate on a point» — «развернуть мысль»."},{"id":2,"question":"Какое выражение на британском английском соответствует «оспорить предположение»?","options":["convey a subtle distinction","build common ground","elaborate on a point","challenge an assumption"],"correctAnswer":"challenge an assumption","explanation":"«challenge an assumption» — «оспорить предположение»."},{"id":3,"question":"Выбери точное русское значение выражения «convey a subtle distinction».","options":["найти точки соприкосновения","передать тонкое различие","сделать вывод","выражаться точно"],"correctAnswer":"передать тонкое различие","explanation":"«convey a subtle distinction» — «передать тонкое различие»."},{"id":4,"question":"Выбери точное русское значение выражения «build common ground».","options":["найти точки соприкосновения","модерировать обсуждение","признать контраргумент","признать обоснованность довода"],"correctAnswer":"найти точки соприкосновения","explanation":"«build common ground» — «найти точки соприкосновения»."},{"id":5,"question":"Какое выражение на британском английском соответствует «сформулировать вопрос нейтрально»?","options":["frame a question neutrally","adapt the register","moderate a discussion","draw an inference"],"correctAnswer":"frame a question neutrally","explanation":"«frame a question neutrally» — «сформулировать вопрос нейтрально»."},{"id":6,"question":"Выбери точное русское значение выражения «qualify a statement».","options":["передать тонкое различие","сформулировать вопрос нейтрально","уточнить оговорками утверждение","сделать вывод"],"correctAnswer":"уточнить оговорками утверждение","explanation":"«qualify a statement» — «уточнить оговорками утверждение»."},{"id":7,"question":"Выбери точное русское значение выражения «draw an inference».","options":["модерировать обсуждение","развернуть мысль","сделать вывод","подобрать стиль общения"],"correctAnswer":"сделать вывод","explanation":"«draw an inference» — «сделать вывод»."},{"id":8,"question":"Какое выражение на британском английском соответствует «модерировать обсуждение»?","options":["build common ground","qualify a statement","elaborate on a point","moderate a discussion"],"correctAnswer":"moderate a discussion","explanation":"«moderate a discussion» — «модерировать обсуждение»."}],"durationMinutes":9}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000006,'quizzes','{"id":760200000000006,"title":"C2 · Разговорный · Знакомство и этикет · Quiz 6","description":"C2: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"📝","xp":48,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"10 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «challenge the underlying premise».","options":["избегать необоснованной уверенности","оспорить исходную предпосылку","выявить ложную дихотомию","провести тонкое различие"],"correctAnswer":"оспорить исходную предпосылку","explanation":"«challenge the underlying premise» — «оспорить исходную предпосылку»."},{"id":2,"question":"Какое выражение на британском английском соответствует «провести тонкое различие»?","options":["reach a considered judgement","maintain rhetorical restraint","make a nuanced distinction","synthesise opposing views"],"correctAnswer":"make a nuanced distinction","explanation":"«make a nuanced distinction» — «провести тонкое различие»."},{"id":3,"question":"Выбери точное русское значение выражения «maintain rhetorical restraint».","options":["выдвинуть на первый план последствия","выявить ложную дихотомию","сохранять риторическую сдержанность","оспорить исходную предпосылку"],"correctAnswer":"сохранять риторическую сдержанность","explanation":"«maintain rhetorical restraint» — «сохранять риторическую сдержанность»."},{"id":4,"question":"Выбери точное русское значение выражения «expose a false dichotomy».","options":["выявить ложную дихотомию","сформулировать оговорку","согласовать разные точки зрения","провести тонкое различие"],"correctAnswer":"выявить ложную дихотомию","explanation":"«expose a false dichotomy» — «выявить ложную дихотомию»."},{"id":5,"question":"Какое выражение на британском английском соответ