INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000008,'quizzes','{"id":760200000000008,"title":"A2 · Разговорный · Повседневные ситуации · Quiz 8","description":"A2: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"📝","xp":25,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"6 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «it depends».","options":["я не уверен","кстати","это зависит от обстоятельств","можно мне"],"correctAnswer":"это зависит от обстоятельств","explanation":"«it depends» — «это зависит от обстоятельств»."},{"id":2,"question":"Какое выражение на британском английском соответствует «дай мне знать»?","options":["I disagree","I am looking for","what do you think?","let me know"],"correctAnswer":"let me know","explanation":"«let me know» — «дай мне знать»."},{"id":3,"question":"Выбери точное русское значение выражения «I disagree».","options":["начнём?","я согласен","я ищу","я не согласен"],"correctAnswer":"я не согласен","explanation":"«I disagree» — «я не согласен»."},{"id":4,"question":"Выбери точное русское значение выражения «I would like».","options":["не торопись","это зависит от обстоятельств","я бы хотел","кстати"],"correctAnswer":"я бы хотел","explanation":"«I would like» — «я бы хотел»."},{"id":5,"question":"Какое выражение на британском английском соответствует «я не уверен»?","options":["could I have","take your time","what do you think?","I am not sure"],"correctAnswer":"I am not sure","explanation":"«I am not sure» — «я не уверен»."},{"id":6,"question":"Выбери точное русское значение выражения «shall we start?».","options":["не торопись","я согласен","я не согласен","начнём?"],"correctAnswer":"начнём?","explanation":"«shall we start?» — «начнём?»."},{"id":7,"question":"Выбери точное русское значение выражения «could I have».","options":["можно мне","не торопись","начнём?","я не согласен"],"correctAnswer":"можно мне","explanation":"«could I have» — «можно мне»."},{"id":8,"question":"Какое выражение на британском английском соответствует «кстати»?","options":["by the way","take your time","let me know","I am looking for"],"correctAnswer":"by the way","explanation":"«by the way» — «кстати»."}],"durationMinutes":6}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000009,'quizzes','{"id":760200000000009,"title":"B1 · Разговорный · Повседневные ситуации · Quiz 9","description":"B1: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"📝","xp":30,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"7 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «take part in».","options":["достичь соглашения","поддерживать связь","принимать участие в","насколько мне известно"],"correctAnswer":"принимать участие в","explanation":"«take part in» — «принимать участие в»."},{"id":2,"question":"Какое выражение на британском английском соответствует «с нетерпением ждать»?","options":["reach an agreement","in my opinion","look forward to","take part in"],"correctAnswer":"look forward to","explanation":"«look forward to» — «с нетерпением ждать»."},{"id":3,"question":"Выбери точное русское значение выражения «in my opinion».","options":["по моему мнению","это звучит разумно","достичь соглашения","насколько мне известно"],"correctAnswer":"по моему мнению","explanation":"«in my opinion» — «по моему мнению»."},{"id":4,"question":"Выбери точное русское значение выражения «reach an agreement».","options":["достичь соглашения","по моему мнению","я понимаю твою точку зрения","принимать участие в"],"correctAnswer":"достичь соглашения","explanation":"«reach an agreement» — «достичь соглашения»."},{"id":5,"question":"Какое выражение на британском английском соответствует «я понимаю твою точку зрения»?","options":["as far as I know","that sounds reasonable","I see your point","make a suggestion"],"correctAnswer":"I see your point","explanation":"«I see your point» — «я понимаю твою точку зрения»."},{"id":6,"question":"Выбери точное русское значение выражения «make a suggestion».","options":["достичь соглашения","поддерживать связь","предложить идею","я понимаю твою точку зрения"],"correctAnswer":"предложить идею","explanation":"«make a suggestion» — «предложить идею»."},{"id":7,"question":"Выбери точное русское значение выражения «that sounds reasonable».","options":["с нетерпением ждать","с другой стороны","я понимаю твою точку зрения","это звучит разумно"],"correctAnswer":"это звучит разумно","explanation":"«that sounds reasonable» — «это звучит разумно»."},{"id":8,"question":"Какое выражение на британском английском соответствует «с другой стороны»?","options":["reach an agreement","clear up a misunderstanding","that sounds reasonable","on the other hand"],"correctAnswer":"on the other hand","explanation":"«on the other hand» — «с другой стороны»."}],"durationMinutes":7}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000010,'quizzes','{"id":760200000000010,"title":"B2 · Разговорный · Повседневные ситуации · Quiz 10","description":"B2: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"📝","xp":35,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"8 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «make a valid point».","options":["выразить иначе","принять во внимание","привести веский аргумент","выразить сомнение"],"correctAnswer":"привести веский аргумент","explanation":"«make a valid point» — «привести веский аргумент»."},{"id":2,"question":"Какое выражение на британском английском соответствует «разобраться с недопониманием»?","options":["weigh up the options","strike a balance","address a misunderstanding","express a reservation"],"correctAnswer":"address a misunderstanding","explanation":"«address a misunderstanding» — «разобраться с недопониманием»."},{"id":3,"question":"Выбери точное русское значение выражения «clarify an assumption».","options":["выразить сомнение","выразить обеспокоенность","прийти к выводу","прояснить предположение"],"correctAnswer":"прояснить предположение","explanation":"«clarify an assumption» — «прояснить предположение»."},{"id":4,"question":"Выбери точное русское значение выражения «have mixed feelings».","options":["прояснить предположение","испытывать смешанные чувства","принять во внимание","разобраться с недопониманием"],"correctAnswer":"испытывать смешанные чувства","explanation":"«have mixed feelings» — «испытывать смешанные чувства»."},{"id":5,"question":"Какое выражение на британском английском соответствует «взвесить варианты»?","options":["raise a concern","weigh up the options","take into account","come to a conclusion"],"correctAnswer":"weigh up the options","explanation":"«weigh up the options» — «взвесить варианты»."},{"id":6,"question":"Выбери точное русское значение выражения «raise a concern».","options":["прийти к выводу","выразить обеспокоенность","привести веский аргумент","испытывать смешанные чувства"],"correctAnswer":"выразить обеспокоенность","explanation":"«raise a concern» — «выразить обеспокоенность»."},{"id":7,"question":"Выбери точное русское значение выражения «put it another way».","options":["выразить сомнение","принять во внимание","выразить иначе","найти баланс"],"correctAnswer":"выразить иначе","explanation":"«put it another way» — «выразить иначе»."},{"id":8,"question":"Какое выражение на британском английском соответствует «выразить сомнение»?","options":["have mixed feelings","weigh up the options","express a reservation","clarify an assumption"],"correctAnswer":"express a reservation","explanation":"«express a reservation» — «выразить сомнение»."}],"durationMinutes":8}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000011,'quizzes','{"id":760200000000011,"title":"C1 · Разговорный · Повседневные ситуации · Quiz 11","description":"C1: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":43,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «convey a subtle distinction».","options":["передать тонкое различие","сделать вывод","признать обоснованность довода","подобрать стиль общения"],"correctAnswer":"передать тонкое различие","explanation":"«convey a subtle distinction» — «передать тонкое различие»."},{"id":2,"question":"Какое выражение на британском английском соответствует «развернуть мысль»?","options":["moderate a discussion","concede a point","elaborate on a point","build common ground"],"correctAnswer":"elaborate on a point","explanation":"«elaborate on a point» — «развернуть мысль»."},{"id":3,"question":"Выбери точное русское значение выражения «challenge an assumption».","options":["найти точки соприкосновения","оспорить предположение","развернуть мысль","уточнить оговорками утверждение"],"correctAnswer":"оспорить предположение","explanation":"«challenge an assumption» — «оспорить предположение»."},{"id":4,"question":"Выбери точное русское значение выражения «build common ground».","options":["передать тонкое различие","найти точки соприкосновения","уточнить оговорками утверждение","подобрать стиль общения"],"correctAnswer":"найти точки соприкосновения","explanation":"«build common ground» — «найти точки соприкосновения»."},{"id":5,"question":"Какое выражение на британском английском соответствует «сформулировать вопрос нейтрально»?","options":["convey a subtle distinction","draw an inference","challenge an assumption","frame a question neutrally"],"correctAnswer":"frame a question neutrally","explanation":"«frame a question neutrally» — «сформулировать вопрос нейтрально»."},{"id":6,"question":"Выбери точное русское значение выражения «qualify a statement».","options":["сделать вывод","найти точки соприкосновения","уточнить оговорками утверждение","выражаться точно"],"correctAnswer":"уточнить оговорками утверждение","explanation":"«qualify a statement» — «уточнить оговорками утверждение»."},{"id":7,"question":"Выбери точное русское значение выражения «concede a point».","options":["признать контраргумент","выражаться точно","признать обоснованность довода","сформулировать вопрос нейтрально"],"correctAnswer":"признать обоснованность довода","explanation":"«concede a point» — «признать обоснованность довода»."},{"id":8,"question":"Какое выражение на британском английском соответствует «выражаться точно»?","options":["qualify a statement","acknowledge a counterargument","challenge an assumption","speak with precision"],"correctAnswer":"speak with precision","explanation":"«speak with precision» — «выражаться точно»."}],"durationMinutes":9}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000012,'quizzes','{"id":760200000000012,"title":"C2 · Разговорный · Повседневные ситуации · Quiz 12","description":"C2: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"📝","xp":45,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"10 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «avoid unwarranted certainty».","options":["предложить ответ с оговорками","избегать необоснованной уверенности","прийти к взвешенному суждению","сформулировать оговорку"],"correctAnswer":"избегать необоснованной уверенности","explanation":"«avoid unwarranted certainty» — «избегать необоснованной уверенности»."},{"id":2,"question":"Какое выражение на британском английском соответствует «разграничить намерение и результат»?","options":["invite a qualified response","distinguish intent from impact","articulate a caveat","expose a false dichotomy"],"correctAnswer":"distinguish intent from impact","explanation":"«distinguish intent from impact» — «разграничить намерение и результат»."},{"id":3,"question":"Выбери точное русское значение выражения «foreground the implications».","options":["выдвинуть на первый план последствия","прийти к взвешенному суждению","сформулировать оговорку","выявить ложную дихотомию"],"correctAnswer":"выдвинуть на первый план последствия","explanation":"«foreground the implications» — «выдвинуть на первый план последствия»."},{"id":4,"question":"Выбери точное русское значение выражения «maintain rhetorical restraint».","options":["выявить ложную дихотомию","синтезировать противоположные взгляды","сохранять риторическую сдержанность","сформулировать оговорку"],"correctAnswer":"сохранять риторическую сдержанность","explanation":"«maintain rhetorical restraint» — «сохранять риторическую сдержанность»."},{"id":5,"question":"Какое выражение на британском английском соответствует «выявить ложную дихотомию»?","options":["avoid unwarranted certainty","foreground the implications","expose a false dichotomy","challenge the underlying premise"],"correctAnswer":"expose a false dichotomy","explanation":"«expose a false dichotomy» — «выявить ложную дихотомию»."},{"id":6,"question":"Выбери точное русское значение выражения «make a nuanced distinction».","options":["оспорить исходную предпосылку","провести тонкое различие","сформулировать оговорку","избегать необоснованной уверенности"],"correctAnswer":"провести тонкое различие","explanation":"«make a nuanced distinction» — «провести тонкое различие»."},{"id":7,"question":"Выбери точное русское значение выражения «reach a considered judgement».","options":["согласовать разные точки зрения","сохранять риторическую сдержанность","прийти к взвешенному суждению","разграничить намерение и результат"],"correctAnswer":"прийти к взвешенному суждению","explanation":"«reach a considered judgement» — «прийти к взвешенному суждению»."},{"id":8,"question":"Какое выражение на британском английском соответствует «предложить ответ с оговорками»?","options":["reconcile competing perspectives","invite a qualified response","synthesise opposing views","avoid unwarranted certainty"],"correctAnswer":"invite a qualified response","explanation":"«invite a qualified response» — «предложить ответ с оговорками»."}],"durationMinutes":10}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000013,'quizzes','{"id":760200000000013,"title":"A1 · Разговорный · Мнение и общение · Quiz 13","description":"A1: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A1","icon":"📝","xp":20,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"5 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «hello».","options":["привет","приятно познакомиться","извините","меня зовут"],"correctAnswer":"привет","explanation":"«hello» — «привет»."},{"id":2,"question":"Какое выражение на британском английском соответствует «как дела?»?","options":["excuse me","how are you?","thank you","my name is"],"correctAnswer":"how are you?","explanation":"«how are you?» — «как дела?»."},{"id":3,"question":"Выбери точное русское значение выражения «I am sorry».","options":["мне жаль","меня зовут","приятно познакомиться","доброе утро"],"correctAnswer":"мне жаль","explanation":"«I am sorry» — «мне жаль»."},{"id":4,"question":"Выбери точное русское значение выражения «my name is».","options":["приятно познакомиться","мне жаль","меня зовут","пожалуйста"],"correctAnswer":"меня зовут","explanation":"«my name is» — «меня зовут»."},{"id":5,"question":"Какое выражение на британском английском соответствует «спасибо»?","options":["excuse me","see you later","hello","thank you"],"correctAnswer":"thank you","explanation":"«thank you» — «спасибо»."},{"id":6,"question":"Выбери точное русское значение выражения «could you help me?».","options":["добрый вечер","не могли бы вы мне помочь?","пожалуйста","спасибо"],"correctAnswer":"не могли бы вы мне помочь?","explanation":"«could you help me?» — «не могли бы вы мне помочь?»."},{"id":7,"question":"Выбери точное русское значение выражения «please».","options":["как дела?","пожалуйста","спасибо","привет"],"correctAnswer":"пожалуйста","explanation":"«please» — «пожалуйста»."},{"id":8,"question":"Какое выражение на британском английском соответствует «увидимся позже»?","options":["see you later","good morning","nice to meet you","thank you"],"correctAnswer":"see you later","explanation":"«see you later» — «увидимся позже»."}],"durationMinutes":5}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000014,'quizzes','{"id":760200000000014,"title":"A2 · Разговорный · Мнение и общение · Quiz 14","description":"A2: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"📝","xp":25,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"6 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «shall we start?».","options":["начнём?","не торопись","можно мне","это зависит от обстоятельств"],"correctAnswer":"начнём?","explanation":"«shall we start?» — «начнём?»."},{"id":2,"question":"Какое выражение на британском английском соответствует «это зависит от обстоятельств»?","options":["it depends","I am not sure","let me know","could I have"],"correctAnswer":"it depends","explanation":"«it depends» — «это зависит от обстоятельств»."},{"id":3,"question":"Выбери точное русское значение выражения «I disagree».","options":["можно мне","дай мне знать","не торопись","я не согласен"],"correctAnswer":"я не согласен","explanation":"«I disagree» — «я не согласен»."},{"id":4,"question":"Выбери точное русское значение выражения «by the way».","options":["кстати","начнём?","я не согласен","дай мне знать"],"correctAnswer":"кстати","explanation":"«by the way» — «кстати»."},{"id":5,"question":"Какое выражение на британском английском соответствует «дай мне знать»?","options":["I would like","could I have","take your time","let me know"],"correctAnswer":"let me know","explanation":"«let me know» — «дай мне знать»."},{"id":6,"question":"Выбери точное русское значение выражения «I would like».","options":["я не уверен","я согласен","я бы хотел","начнём?"],"correctAnswer":"я бы хотел","explanation":"«I would like» — «я бы хотел»."},{"id":7,"question":"Выбери точное русское значение выражения «I am not sure».","options":["можно мне","это зависит от обстоятельств","я не уверен","начнём?"],"correctAnswer":"я не уверен","explanation":"«I am not sure» — «я не уверен»."},{"id":8,"question":"Какое выражение на британском английском соответствует «что ты думаешь?»?","options":["take your time","could I have","it depends","what do you think?"],"correctAnswer":"what do you think?","explanation":"«what do you think?» — «что ты думаешь?»."}],"durationMinutes":6}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000015,'quizzes','{"id":760200000000015,"title":"B1 · Разговорный · Мнение и общение · Quiz 15","description":"B1: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"📝","xp":30,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"7 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «clear up a misunderstanding».","options":["по моему мнению","с другой стороны","достичь соглашения","прояснить недоразумение"],"correctAnswer":"прояснить недоразумение","explanation":"«clear up a misunderstanding» — «прояснить недоразумение»."},{"id":2,"question":"Какое выражение на британском английском соответствует «предложить идею»?","options":["make a suggestion","look forward to","that sounds reasonable","take part in"],"correctAnswer":"make a suggestion","explanation":"«make a suggestion» — «предложить идею»."},{"id":3,"question":"Выбери точное русское значение выражения «reach an agreement».","options":["насколько мне известно","достичь соглашения","прояснить недоразумение","по моему мнению"],"correctAnswer":"достичь соглашения","explanation":"«reach an agreement» — «достичь соглашения»."},{"id":4,"question":"Выбери точное русское значение выражения «look forward to».","options":["по моему мнению","я понимаю твою точку зрения","с нетерпением ждать","насколько мне известно"],"correctAnswer":"с нетерпением ждать","explanation":"«look forward to» — «с нетерпением ждать»."},{"id":5,"question":"Какое выражение на британском английском соответствует «с другой стороны»?","options":["make a suggestion","in my opinion","on the other hand","take part in"],"correctAnswer":"on the other hand","explanation":"«on the other hand» — «с другой стороны»."},{"id":6,"question":"Выбери точное русское значение выражения «I see your point».","options":["поддерживать связь","предложить идею","я понимаю твою точку зрения","с другой стороны"],"correctAnswer":"я понимаю твою точку зрения","explanation":"«I see your point» — «я понимаю твою точку зрения»."},{"id":7,"question":"Выбери точное русское значение выражения «to be honest».","options":["поддерживать связь","если честно","прояснить недоразумение","по моему мнению"],"correctAnswer":"если честно","explanation":"«to be honest» — «если честно»."},{"id":8,"question":"Какое выражение на британском английском соответствует «насколько мне известно»?","options":["as far as I know","look forward to","on the other hand","clear up a misunderstanding"],"correctAnswer":"as far as I know","explanation":"«as far as I know» — «насколько мне известно»."}],"durationMinutes":7}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000016,'quizzes','{"id":760200000000016,"title":"B2 · Разговорный · Мнение и общение · Quiz 16","description":"B2: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"📝","xp":38,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"8 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «put it another way».","options":["ответить тактично","принять во внимание","взвесить варианты","выразить иначе"],"correctAnswer":"выразить иначе","explanation":"«put it another way» — «выразить иначе»."},{"id":2,"question":"Какое выражение на британском английском соответствует «выразить сомнение»?","options":["raise a concern","make a valid point","take into account","express a reservation"],"correctAnswer":"express a reservation","explanation":"«express a reservation» — «выразить сомнение»."},{"id":3,"question":"Выбери точное русское значение выражения «respond tactfully».","options":["найти баланс","испытывать смешанные чувства","ответить тактично","выразить сомнение"],"correctAnswer":"ответить тактично","explanation":"«respond tactfully» — «ответить тактично»."},{"id":4,"question":"Выбери точное русское значение выражения «make a valid point».","options":["найти баланс","выразить обеспокоенность","ответить тактично","привести веский аргумент"],"correctAnswer":"привести веский аргумент","explanation":"«make a valid point» — «привести веский аргумент»."},{"id":5,"question":"Какое выражение на британском английском соответствует «прояснить предположение»?","options":["strike a balance","have mixed feelings","clarify an assumption","make a valid point"],"correctAnswer":"clarify an assumption","explanation":"«clarify an assumption» — «прояснить предположение»."},{"id":6,"question":"Выбери точное русское значение выражения «take into account».","options":["выразить обеспокоенность","принять во внимание","испытывать смешанные чувства","взвесить варианты"],"correctAnswer":"принять во внимание","explanation":"«take into account» — «принять во внимание»."},{"id":7,"question":"Выбери точное русское значение выражения «raise a concern».","options":["выразить обеспокоенность","принять во внимание","прояснить предположение","ответить тактично"],"correctAnswer":"выразить обеспокоенность","explanation":"«raise a concern» — «выразить обеспокоенность»."},{"id":8,"question":"Какое выражение на британском английском соответствует «найти баланс»?","options":["weigh up the options","take into account","put it another way","strike a balance"],"correctAnswer":"strike a balance","explanation":"«strike a balance» — «найти баланс»."}],"durationMinutes":8}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000017,'quizzes','{"id":760200000000017,"title":"C1 · Разговорный · Мнение и общение · Quiz 17","description":"C1: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":40,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «convey a subtle distinction».","options":["модерировать обсуждение","передать тонкое различие","признать обоснованность довода","признать контраргумент"],"correctAnswer":"передать тонкое различие","explanation":"«convey a subtle distinction» — «передать тонкое различие»."},{"id":2,"question":"Какое выражение на британском английском соответствует «найти точки соприкосновения»?","options":["acknowledge a counterargument","convey a subtle distinction","build common ground","speak with precision"],"correctAnswer":"build common ground","explanation":"«build common ground» — «найти точки соприкосновения»."},{"id":3,"question":"Выбери точное русское значение выражения «acknowledge a counterargument».","options":["признать обоснованность довода","признать контраргумент","подобрать стиль общения","сделать вывод"],"correctAnswer":"признать контраргумент","explanation":"«acknowledge a counterargument» — «признать контраргумент»."},{"id":4,"question":"Выбери точное русское значение выражения «qualify a statement».","options":["модерировать обсуждение","сделать вывод","уточнить оговорками утверждение","подобрать стиль общения"],"correctAnswer":"уточнить оговорками утверждение","explanation":"«qualify a statement» — «уточнить оговорками утверждение»."},{"id":5,"question":"Какое выражение на британском английском соответствует «модерировать обсуждение»?","options":["frame a question neutrally","moderate a discussion","concede a point","convey a subtle distinction"],"correctAnswer":"moderate a discussion","explanation":"«moderate a discussion» — «модерировать обсуждение»."},{"id":6,"question":"Выбери точное русское значение выражения «draw an inference».","options":["модерировать обсуждение","развернуть мысль","подобрать стиль общения","сделать вывод"],"correctAnswer":"сделать вывод","explanation":"«draw an inference» — «сделать вывод»."},{"id":7,"question":"Выбери точное русское значение выражения «concede a point».","options":["признать контраргумент","оспорить предположение","сформулировать вопрос нейтрально","признать обоснованность довода"],"correctAnswer":"признать обоснованность довода","explanation":"«concede a point» — «признать обоснованность довода»."},{"id":8,"question":"Какое выражение на британском английском соответствует «выражаться точно»?","options":["concede a point","build common ground","speak with precision","challenge an assumption"],"correctAnswer":"speak with precision","explanation":"«speak with precision» — «выражаться точно»."}],"durationMinutes":9}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000018,'quizzes','{"id":760200000000018,"title":"C2 · Разговорный · Мнение и общение · Quiz 18","description":"C2: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"📝","xp":45,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"10 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «invite a qualified response».","options":["выявить ложную дихотомию","выдвинуть на первый план последствия","сохранять риторическую сдержанность","предложить ответ с оговорками"],"correctAnswer":"предложить ответ с оговорками","explanation":"«invite a qualified response» — «предложить ответ с оговорками»."},{"id":2,"question":"Какое выражение на британском английском соответствует «выявить ложную дихотомию»?","options":["make a nuanced distinction","reach a considered judgement","expose a false dichotomy","distinguish intent from impact"],"correctAnswer":"expose a false dichotomy","explanation":"«expose a false dichotomy» — «выявить ложную дихотомию»."},{"id":3,"question":"Выбери точное русское значение выражения «synthesise opposing views».","options":["сохранять риторическую сдержанность","синтезировать противоположные взгляды","выдвинуть на первый план последствия","выявить ложную дихотомию"],"correctAnswer":"синтезировать противоположные взгляды","explanation":"«synthesise opposing views» — «синтезировать противоположные взгляды»."},{"id":4,"question":"Выбери точное русское значение выражения «avoid unwarranted certainty».","options":["избегать необоснованной уверенности","сохранять риторическую сдержанность","разграничить намерение и результат","предложить ответ с оговорками"],"correctAnswer":"избегать необоснованной уверенности","explanation":"«avoid unwarranted certainty» — «избегать необоснованной уверенности»."},{"id":5,"question":"Какое выражение на британском английском соответствует «сохранять риторическую сдержанность»?","options":["make a nuanced distinction","reconcile competing perspectives","expose a false dichotomy","maintain rhetorical restraint"],"correctAnswer":"maintain rhetorical restraint","explanation":"«maintain rhetorical restraint» — «сохранять риторическую сдержанность»."},{"id":6,"question":"Выбери точное русское значение выражения «make a nuanced distinction».","options":["сохранять риторическую сдержанность","провести тонкое различие","синтезировать противоположные взгляды","разграничить намерение и результат"],"correctAnswer":"провести тонкое различие","explanation":"«make a nuanced distinction» — «провести тонкое различие»."},{"id":7,"question":"Выбери точное русское значение выражения «distinguish intent from impact».","options":["предложить ответ с оговорками","разграничить намерение и результат","синтезировать противоположные взгляды","сформулировать оговорку"],"correctAnswer":"разграничить намерение и результат","explanation":"«distinguish intent from impact» — «разграничить намерение и результат»."},{"id":8,"question":"Какое выражение на британском английском соответствует «сформулировать оговорку»?","options":["articulate a caveat","expose a false dichotomy","challenge the underlying premise","synthesise opposing views"],"correctAnswer":"articulate a caveat","explanation":"«articulate a caveat» — «сформулировать оговорку»."}],"durationMinutes":10}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
