ро","explanation":"«good morning» — «доброе утро»."},{"id":8,"question":"Какое выражение на британском английском соответствует «мне жаль»?","options":["my name is","nice to meet you","see you later","I am sorry"],"correctAnswer":"I am sorry","explanation":"«I am sorry» — «мне жаль»."}],"durationMinutes":5}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000020,'quizzes','{"id":760200000000020,"title":"A2 · Разговорный · Диалог и уточнение · Quiz 20","description":"A2: диалог и уточнение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"📝","xp":25,"category":"Диалог и уточнение","track":"Разговорный","topic":"Диалог и уточнение","duration":"6 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «I agree».","options":["я бы хотел","начнём?","я согласен","дай мне знать"],"correctAnswer":"я согласен","explanation":"«I agree» — «я согласен»."},{"id":2,"question":"Какое выражение на британском английском соответствует «я не уверен»?","options":["I am not sure","take your time","I agree","could I have"],"correctAnswer":"I am not sure","explanation":"«I am not sure» — «я не уверен»."},{"id":3,"question":"Выбери точное русское значение выражения «I disagree».","options":["я не согласен","что ты думаешь?","это зависит от обстоятельств","я не уверен"],"correctAnswer":"я не согласен","explanation":"«I disagree» — «я не согласен»."},{"id":4,"question":"Выбери точное русское значение выражения «shall we start?».","options":["я ищу","можно мне","начнём?","я бы хотел"],"correctAnswer":"начнём?","explanation":"«shall we start?» — «начнём?»."},{"id":5,"question":"Какое выражение на британском английском соответствует «дай мне знать»?","options":["I would like","could I have","shall we start?","let me know"],"correctAnswer":"let me know","explanation":"«let me know» — «дай мне знать»."},{"id":6,"question":"Выбери точное русское значение выражения «take your time».","options":["я согласен","кстати","дай мне знать","не торопись"],"correctAnswer":"не торопись","explanation":"«take your time» — «не торопись»."},{"id":7,"question":"Выбери точное русское значение выражения «it depends».","options":["это зависит от обстоятельств","можно мне","я согласен","начнём?"],"correctAnswer":"это зависит от обстоятельств","explanation":"«it depends» — «это зависит от обстоятельств»."},{"id":8,"question":"Какое выражение на британском английском соответствует «кстати»?","options":["by the way","let me know","I would like","I am not sure"],"correctAnswer":"by the way","explanation":"«by the way» — «кстати»."}],"durationMinutes":6}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000021,'quizzes','{"id":760200000000021,"title":"B1 · Разговорный · Диалог и уточнение · Quiz 21","description":"B1: диалог и уточнение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"📝","xp":33,"category":"Диалог и уточнение","track":"Разговорный","topic":"Диалог и уточнение","duration":"7 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «to be honest».","options":["я понимаю твою точку зрения","поддерживать связь","с нетерпением ждать","если честно"],"correctAnswer":"если честно","explanation":"«to be honest» — «если честно»."},{"id":2,"question":"Какое выражение на британском английском соответствует «с другой стороны»?","options":["as far as I know","make a suggestion","on the other hand","take part in"],"correctAnswer":"on the other hand","explanation":"«on the other hand» — «с другой стороны»."},{"id":3,"question":"Выбери точное русское значение выражения «in my opinion».","options":["по моему мнению","насколько мне известно","с нетерпением ждать","с другой стороны"],"correctAnswer":"по моему мнению","explanation":"«in my opinion» — «по моему мнению»."},{"id":4,"question":"Выбери точное русское значение выражения «reach an agreement».","options":["прояснить недоразумение","достичь соглашения","если честно","принимать участие в"],"correctAnswer":"достичь соглашения","explanation":"«reach an agreement» — «достичь соглашения»."},{"id":5,"question":"Какое выражение на британском английском соответствует «я понимаю твою точку зрения»?","options":["in my opinion","I see your point","that sounds reasonable","to be honest"],"correctAnswer":"I see your point","explanation":"«I see your point» — «я понимаю твою точку зрения»."},{"id":6,"question":"Выбери точное русское значение выражения «that sounds reasonable».","options":["поддерживать связь","это звучит разумно","по моему мнению","с нетерпением ждать"],"correctAnswer":"это звучит разумно","explanation":"«that sounds reasonable» — «это звучит разумно»."},{"id":7,"question":"Выбери точное русское значение выражения «look forward to».","options":["принимать участие в","с нетерпением ждать","по моему мнению","с другой стороны"],"correctAnswer":"с нетерпением ждать","explanation":"«look forward to» — «с нетерпением ждать»."},{"id":8,"question":"Какое выражение на британском английском соответствует «предложить идею»?","options":["make a suggestion","look forward to","that sounds reasonable","on the other hand"],"correctAnswer":"make a suggestion","explanation":"«make a suggestion» — «предложить идею»."}],"durationMinutes":7}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000022,'quizzes','{"id":760200000000022,"title":"B2 · Разговорный · Диалог и уточнение · Quiz 22","description":"B2: диалог и уточнение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"📝","xp":35,"category":"Диалог и уточнение","track":"Разговорный","topic":"Диалог и уточнение","duration":"8 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «respond tactfully».","options":["выразить обеспокоенность","найти баланс","разобраться с недопониманием","ответить тактично"],"correctAnswer":"ответить тактично","explanation":"«respond tactfully» — «ответить тактично»."},{"id":2,"question":"Какое выражение на британском английском соответствует «найти баланс»?","options":["come to a conclusion","raise a concern","clarify an assumption","strike a balance"],"correctAnswer":"strike a balance","explanation":"«strike a balance» — «найти баланс»."},{"id":3,"question":"Выбери точное русское значение выражения «come to a conclusion».","options":["прийти к выводу","выразить иначе","взвесить варианты","выразить обеспокоенность"],"correctAnswer":"прийти к выводу","explanation":"«come to a conclusion» — «прийти к выводу»."},{"id":4,"question":"Выбери точное русское значение выражения «take into account».","options":["взвесить варианты","принять во внимание","выразить иначе","выразить сомнение"],"correctAnswer":"принять во внимание","explanation":"«take into account» — «принять во внимание»."},{"id":5,"question":"Какое выражение на британском английском соответствует «разобраться с недопониманием»?","options":["make a valid point","have mixed feelings","weigh up the options","address a misunderstanding"],"correctAnswer":"address a misunderstanding","explanation":"«address a misunderstanding» — «разобраться с недопониманием»."},{"id":6,"question":"Выбери точное русское значение выражения «clarify an assumption».","options":["прийти к выводу","прояснить предположение","выразить сомнение","ответить тактично"],"correctAnswer":"прояснить предположение","explanation":"«clarify an assumption» — «прояснить предположение»."},{"id":7,"question":"Выбери точное русское значение выражения «express a reservation».","options":["выразить сомнение","найти баланс","взвесить варианты","ответить тактично"],"correctAnswer":"выразить сомнение","explanation":"«express a reservation» — «выразить сомнение»."},{"id":8,"question":"Какое выражение на британском английском соответствует «испытывать смешанные чувства»?","options":["take into account","express a reservation","have mixed feelings","raise a concern"],"correctAnswer":"have mixed feelings","explanation":"«have mixed feelings» — «испытывать смешанные чувства»."}],"durationMinutes":8}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000023,'quizzes','{"id":760200000000023,"title":"C1 · Разговорный · Диалог и уточнение · Quiz 23","description":"C1: диалог и уточнение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":40,"category":"Диалог и уточнение","track":"Разговорный","topic":"Диалог и уточнение","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «moderate a discussion».","options":["модерировать обсуждение","выражаться точно","развернуть мысль","сформулировать вопрос нейтрально"],"correctAnswer":"модерировать обсуждение","explanation":"«moderate a discussion» — «модерировать обсуждение»."},{"id":2,"question":"Какое выражение на британском английском соответствует «выражаться точно»?","options":["moderate a discussion","speak with precision","build common ground","frame a question neutrally"],"correctAnswer":"speak with precision","explanation":"«speak with precision» — «выражаться точно»."},{"id":3,"question":"Выбери точное русское значение выражения «adapt the register».","options":["признать контраргумент","подобрать стиль общения","сделать вывод","оспорить предположение"],"correctAnswer":"подобрать стиль общения","explanation":"«adapt the register» — «подобрать стиль общения»."},{"id":4,"question":"Выбери точное русское значение выражения «build common ground».","options":["найти точки соприкосновения","признать контраргумент","передать тонкое различие","выражаться точно"],"correctAnswer":"найти точки соприкосновения","explanation":"«build common ground» — «найти точки соприкосновения»."},{"id":5,"question":"Какое выражение на британском английском соответствует «уточнить оговорками утверждение»?","options":["elaborate on a point","acknowledge a counterargument","frame a question neutrally","qualify a statement"],"correctAnswer":"qualify a statement","explanation":"«qualify a statement» — «уточнить оговорками утверждение»."},{"id":6,"question":"Выбери точное русское значение выражения «elaborate on a point».","options":["сделать вывод","развернуть мысль","выражаться точно","модерировать обсуждение"],"correctAnswer":"развернуть мысль","explanation":"«elaborate on a point» — «развернуть мысль»."},{"id":7,"question":"Выбери точное русское значение выражения «challenge an assumption».","options":["признать контраргумент","передать тонкое различие","признать обоснованность довода","оспорить предположение"],"correctAnswer":"оспорить предположение","explanation":"«challenge an assumption» — «оспорить предположение»."},{"id":8,"question":"Какое выражение на британском английском соответствует «признать обоснованность довода»?","options":["concede a point","convey a subtle distinction","elaborate on a point","adapt the register"],"correctAnswer":"concede a point","explanation":"«concede a point» — «признать обоснованность довода»."}],"durationMinutes":9}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000024,'quizzes','{"id":760200000000024,"title":"C2 · Разговорный · Диалог и уточнение · Quiz 24","description":"C2: диалог и уточнение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"📝","xp":45,"category":"Диалог и уточнение","track":"Разговорный","topic":"Диалог и уточнение","duration":"10 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «avoid unwarranted certainty».","options":["согласовать разные точки зрения","выдвинуть на первый план последствия","выявить ложную дихотомию","избегать необоснованной уверенности"],"correctAnswer":"избегать необоснованной уверенности","explanation":"«avoid unwarranted certainty» — «избегать необоснованной уверенности»."},{"id":2,"question":"Какое выражение на британском английском соответствует «выявить ложную дихотомию»?","options":["challenge the underlying premise","articulate a caveat","expose a false dichotomy","distinguish intent from impact"],"correctAnswer":"expose a false dichotomy","explanation":"«expose a false dichotomy» — «выявить ложную дихотомию»."},{"id":3,"question":"Выбери точное русское значение выражения «invite a qualified response».","options":["предложить ответ с оговорками","выдвинуть на первый план последствия","разграничить намерение и результат","прийти к взвешенному суждению"],"correctAnswer":"предложить ответ с оговорками","explanation":"«invite a qualified response» — «предложить ответ с оговорками»."},{"id":4,"question":"Выбери точное русское значение выражения «make a nuanced distinction».","options":["провести тонкое различие","прийти к взвешенному суждению","согласовать разные точки зрения","оспорить исходную предпосылку"],"correctAnswer":"провести тонкое различие","explanation":"«make a nuanced distinction» — «провести тонкое различие»."},{"id":5,"question":"Какое выражение на британском английском соответствует «разграничить намерение и результат»?","options":["foreground the implications","distinguish intent from impact","reconcile competing perspectives","make a nuanced distinction"],"correctAnswer":"distinguish intent from impact","explanation":"«distinguish intent from impact» — «разграничить намерение и результат»."},{"id":6,"question":"Выбери точное русское значение выражения «synthesise opposing views».","options":["провести тонкое различие","оспорить исходную предпосылку","согласовать разные точки зрения","синтезировать противоположные взгляды"],"correctAnswer":"синтезировать противоположные взгляды","explanation":"«synthesise opposing views» — «синтезировать противоположные взгляды»."},{"id":7,"question":"Выбери точное русское значение выражения «maintain rhetorical restraint».","options":["сохранять риторическую сдержанность","согласовать разные точки зрения","синтезировать противоположные взгляды","избегать необоснованной уверенности"],"correctAnswer":"сохранять риторическую сдержанность","explanation":"«maintain rhetorical restraint» — «сохранять риторическую сдержанность»."},{"id":8,"question":"Какое выражение на британском английском соответствует «согласовать разные точки зрения»?","options":["expose a false dichotomy","maintain rhetorical restraint","reconcile competing perspectives","articulate a caveat"],"correctAnswer":"reconcile competing perspectives","explanation":"«reconcile competing perspectives» — «согласовать разные точки зрения»."}],"durationMinutes":10}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
