INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000028,'quizzes','{"id":760200000000028,"title":"B2 · Разговорный · Точность высказывания · Quiz 28","description":"B2: точность высказывания. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"📝","xp":35,"category":"Точность высказывания","track":"Разговорный","topic":"Точность высказывания","duration":"8 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «take into account».","options":["найти баланс","прийти к выводу","принять во внимание","выразить обеспокоенность"],"correctAnswer":"принять во внимание","explanation":"«take into account» — «принять во внимание»."},{"id":2,"question":"Какое выражение на британском английском соответствует «выразить сомнение»?","options":["have mixed feelings","express a reservation","come to a conclusion","address a misunderstanding"],"correctAnswer":"express a reservation","explanation":"«express a reservation» — «выразить сомнение»."},{"id":3,"question":"Выбери точное русское значение выражения «strike a balance».","options":["найти баланс","прояснить предположение","выразить сомнение","испытывать смешанные чувства"],"correctAnswer":"найти баланс","explanation":"«strike a balance» — «найти баланс»."},{"id":4,"question":"Выбери точное русское значение выражения «respond tactfully».","options":["ответить тактично","выразить обеспокоенность","взвесить варианты","найти баланс"],"correctAnswer":"ответить тактично","explanation":"«respond tactfully» — «ответить тактично»."},{"id":5,"question":"Какое выражение на британском английском соответствует «выразить обеспокоенность»?","options":["express a reservation","address a misunderstanding","raise a concern","weigh up the options"],"correctAnswer":"raise a concern","explanation":"«raise a concern» — «выразить обеспокоенность»."},{"id":6,"question":"Выбери точное русское значение выражения «come to a conclusion».","options":["прийти к выводу","ответить тактично","найти баланс","разобраться с недопониманием"],"correctAnswer":"прийти к выводу","explanation":"«come to a conclusion» — «прийти к выводу»."},{"id":7,"question":"Выбери точное русское значение выражения «make a valid point».","options":["привести веский аргумент","принять во внимание","найти баланс","испытывать смешанные чувства"],"correctAnswer":"привести веский аргумент","explanation":"«make a valid point» — «привести веский аргумент»."},{"id":8,"question":"Какое выражение на британском английском соответствует «выразить иначе»?","options":["come to a conclusion","put it another way","have mixed feelings","weigh up the options"],"correctAnswer":"put it another way","explanation":"«put it another way» — «выразить иначе»."}],"durationMinutes":8}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000029,'quizzes','{"id":760200000000029,"title":"C1 · Разговорный · Точность высказывания · Quiz 29","description":"C1: точность высказывания. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":40,"category":"Точность высказывания","track":"Разговорный","topic":"Точность высказывания","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «challenge an assumption».","options":["сделать вывод","выражаться точно","сформулировать вопрос нейтрально","оспорить предположение"],"correctAnswer":"оспорить предположение","explanation":"«challenge an assumption» — «оспорить предположение»."},{"id":2,"question":"Какое выражение на британском английском соответствует «развернуть мысль»?","options":["challenge an assumption","elaborate on a point","adapt the register","convey a subtle distinction"],"correctAnswer":"elaborate on a point","explanation":"«elaborate on a point» — «развернуть мысль»."},{"id":3,"question":"Выбери точное русское значение выражения «convey a subtle distinction».","options":["развернуть мысль","оспорить предположение","передать тонкое различие","выражаться точно"],"correctAnswer":"передать тонкое различие","explanation":"«convey a subtle distinction» — «передать тонкое различие»."},{"id":4,"question":"Выбери точное русское значение выражения «build common ground».","options":["сделать вывод","найти точки соприкосновения","признать обоснованность довода","передать тонкое различие"],"correctAnswer":"найти точки соприкосновения","explanation":"«build common ground» — «найти точки соприкосновения»."},{"id":5,"question":"Какое выражение на британском английском соответствует «модерировать обсуждение»?","options":["challenge an assumption","frame a question neutrally","moderate a discussion","convey a subtle distinction"],"correctAnswer":"moderate a discussion","explanation":"«moderate a discussion» — «модерировать обсуждение»."},{"id":6,"question":"Выбери точное русское значение выражения «acknowledge a counterargument».","options":["признать контраргумент","передать тонкое различие","развернуть мысль","найти точки соприкосновения"],"correctAnswer":"признать контраргумент","explanation":"«acknowledge a counterargument» — «признать контраргумент»."},{"id":7,"question":"Выбери точное русское значение выражения «adapt the register».","options":["оспорить предположение","развернуть мысль","подобрать стиль общения","сделать вывод"],"correctAnswer":"подобрать стиль общения","explanation":"«adapt the register» — «подобрать стиль общения»."},{"id":8,"question":"Какое выражение на британском английском соответствует «сделать вывод»?","options":["convey a subtle distinction","draw an inference","qualify a statement","acknowledge a counterargument"],"correctAnswer":"draw an inference","explanation":"«draw an inference» — «сделать вывод»."}],"durationMinutes":9}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000030,'quizzes','{"id":760200000000030,"title":"C2 · Разговорный · Точность высказывания · Quiz 30","description":"C2: точность высказывания. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"📝","xp":45,"category":"Точность высказывания","track":"Разговорный","topic":"Точность высказывания","duration":"10 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «reconcile competing perspectives».","options":["предложить ответ с оговорками","сформулировать оговорку","прийти к взвешенному суждению","согласовать разные точки зрения"],"correctAnswer":"согласовать разные точки зрения","explanation":"«reconcile competing perspectives» — «согласовать разные точки зрения»."},{"id":2,"question":"Какое выражение на британском английском соответствует «оспорить исходную предпосылку»?","options":["maintain rhetorical restraint","synthesise opposing views","challenge the underlying premise","invite a qualified response"],"correctAnswer":"challenge the underlying premise","explanation":"«challenge the underlying premise» — «оспорить исходную предпосылку»."},{"id":3,"question":"Выбери точное русское значение выражения «synthesise opposing views».","options":["разграничить намерение и результат","предложить ответ с оговорками","прийти к взвешенному суждению","синтезировать противоположные взгляды"],"correctAnswer":"синтезировать противоположные взгляды","explanation":"«synthesise opposing views» — «синтезировать противоположные взгляды»."},{"id":4,"question":"Выбери точное русское значение выражения «reach a considered judgement».","options":["прийти к взвешенному суждению","предложить ответ с оговорками","выдвинуть на первый план последствия","оспорить исходную предпосылку"],"correctAnswer":"прийти к взвешенному суждению","explanation":"«reach a considered judgement» — «прийти к взвешенному суждению»."},{"id":5,"question":"Какое выражение на британском английском соответствует «предложить ответ с оговорками»?","options":["avoid unwarranted certainty","foreground the implications","invite a qualified response","articulate a caveat"],"correctAnswer":"invite a qualified response","explanation":"«invite a qualified response» — «предложить ответ с оговорками»."},{"id":6,"question":"Выбери точное русское значение выражения «avoid unwarranted certainty».","options":["сохранять риторическую сдержанность","синтезировать противоположные взгляды","сформулировать оговорку","избегать необоснованной уверенности"],"correctAnswer":"избегать необоснованной уверенности","explanation":"«avoid unwarranted certainty» — «избегать необоснованной уверенности»."},{"id":7,"question":"Выбери точное русское значение выражения «expose a false dichotomy».","options":["оспорить исходную предпосылку","выявить ложную дихотомию","сохранять риторическую сдержанность","прийти к взвешенному суждению"],"correctAnswer":"выявить ложную дихотомию","explanation":"«expose a false dichotomy» — «выявить ложную дихотомию»."},{"id":8,"question":"Какое выражение на британском английском соответствует «выдвинуть на первый план последствия»?","options":["articulate a caveat","reconcile competing perspectives","challenge the underlying premise","foreground the implications"],"correctAnswer":"foreground the implications","explanation":"«foreground the implications» — «выдвинуть на первый план последствия»."}],"durationMinutes":10}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
