INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000032,'quizzes','{"id":760200000000032,"title":"A2 · Разговорный · Знакомство и этикет · Quiz 32","description":"A2: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"📝","xp":25,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"6 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «I disagree».","options":["я согласен","я не согласен","начнём?","я не уверен"],"correctAnswer":"я не согласен","explanation":"«I disagree» — «я не согласен»."},{"id":2,"question":"Какое выражение на британском английском соответствует «что ты думаешь?»?","options":["I would like","what do you think?","by the way","could I have"],"correctAnswer":"what do you think?","explanation":"«what do you think?» — «что ты думаешь?»."},{"id":3,"question":"Выбери точное русское значение выражения «let me know».","options":["я согласен","начнём?","дай мне знать","можно мне"],"correctAnswer":"дай мне знать","explanation":"«let me know» — «дай мне знать»."},{"id":4,"question":"Выбери точное русское значение выражения «I agree».","options":["я ищу","я согласен","не торопись","что ты думаешь?"],"correctAnswer":"я согласен","explanation":"«I agree» — «я согласен»."},{"id":5,"question":"Какое выражение на британском английском соответствует «можно мне»?","options":["shall we start?","I would like","it depends","could I have"],"correctAnswer":"could I have","explanation":"«could I have» — «можно мне»."},{"id":6,"question":"Выбери точное русское значение выражения «by the way».","options":["я бы хотел","можно мне","кстати","я не согласен"],"correctAnswer":"кстати","explanation":"«by the way» — «кстати»."},{"id":7,"question":"Выбери точное русское значение выражения «take your time».","options":["не торопись","что ты думаешь?","это зависит от обстоятел