INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000033,'quizzes','{"id":760200000000033,"title":"B1 · Разговорный · Знакомство и этикет · Quiz 33","description":"B1: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"📝","xp":30,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"7 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «clear up a misunderstanding».","options":["прояснить недоразумение","достичь соглашения","насколько мне известно","предложить идею"],"correctAnswer":"прояснить недоразумение","explanation":"«clear up a misunderstanding» — «прояснить недоразумение»."},{"id":2,"question":"Какое выражение на британском английском соответствует «насколько мне известно»?","options":["as far as I know","I see your point","take part in","on the other hand"],"correctAnswer":"as far as I know","explanation":"«as far as I know» — «насколько мне известно»."},{"id":3,"question":"Выбери точное русское значение выражения «make a suggestion».","options":["предложить идею","по моему мнению","это звучит разумно","с нетерпением ждать"],"correctAnswer":"предложить идею","explanation":"«make a suggestion» — «предложить идею»."},{"id":4,"question":"Выбери точное русское значение выражения «in my opinion».","options":["по моему мнению","если честно","я понимаю твою точку зрения","прояснить недоразумение"],"correctAnswer":"по моему мнению","explanation":"«in my opinion» — «по моему мнению»."},{"id":5,"question":"Какое выражение на британском английском соответствует «достичь соглашения»?","options":["take part in","that sounds reasonable","clear up a misunderstanding","reach an agreement"],"correctAnswer":"reach an agreement","explanation":"«reach an agreement» — «достичь соглашения»."},{"id":6,"question":"Выбери точное русское значение выражения «I see your point».","options":["по моему мнению","я понимаю твою точку зрения","с нетерпением ждать","поддерживать связь"],"correctAnswer":"я понимаю твою точку зрения","explanation":"«I see your point» — «я понимаю твою точку зрения»."},{"id":7,"question":"Выбери точное русское значение выражения «on the other hand».","options":["достичь соглашения","это звучит разумно","принимать участие в","с другой стороны"],"correctAnswer":"с другой стороны","explanation":"«on the other hand» — «с другой стороны»."},{"id":8,"question":"Какое выражение на британском английском соответствует «это звучит разумно»?","options":["to be honest","look forward to","I see your point","that sounds reasonable"],"correctAnswer":"that sounds reasonable","explanation":"«that sounds reasonable» — «это звучит разумно»."}],"durationMinutes":7}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000034,'quizzes','{"id":760200000000034,"title":"B2 · Разговорный · Знакомство и этикет · Quiz 34","description":"B2: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"📝","xp":35,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"8 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «put it another way».","options":["ответить тактично","прояснить предположение","выразить иначе","разобраться с недопониманием"],"correctAnswer":"выразить иначе","explanation":"«put it another way» — «выразить иначе»."},{"id":2,"question":"Какое выражение на британском английском соответствует «найти баланс»?","options":["make a valid point","strike a balance","take into account","express a reservation"],"correctAnswer":"strike a balance","explanation":"«strike a balance» — «найти баланс»."},{"id":3,"question":"Выбери точное русское значение выражения «make a valid point».","options":["выразить обеспокоенность","разобраться с недопониманием","привести веский аргумент","взвесить варианты"],"correctAnswer":"привести веский аргумент","explanation":"«make a valid point» — «привести веский аргумент»."},{"id":4,"question":"Выбери точное русское значение выражения «express a reservation».","options":["выразить обеспокоенность","привести веский аргумент","взвесить варианты","выразить сомнение"],"correctAnswer":"выразить сомнение","explanation":"«express a reservation» — «выразить сомнение»."},{"id":5,"question":"Какое выражение на британском английском соответствует «взвесить варианты»?","options":["have mixed feelings","express a reservation","weigh up the options","make a valid point"],"correctAnswer":"weigh up the options","explanation":"«weigh up the options» — «взвесить варианты»."},{"id":6,"question":"Выбери точное русское значение выражения «take into account».","options":["выразить обеспокоенность","найти баланс","принять во внимание","выразить иначе"],"correctAnswer":"принять во внимание","explanation":"«take into account» — «принять во внимание»."},{"id":7,"question":"Выбери точное русское значение выражения «respond tactfully».","options":["ответить тактично","найти баланс","разобраться с недопониманием","взвесить варианты"],"correctAnswer":"ответить тактично","explanation":"«respond tactfully» — «ответить тактично»."},{"id":8,"question":"Какое выражение на британском английском соответствует «выразить обеспокоенность»?","options":["strike a balance","respond tactfully","raise a concern","make a valid point"],"correctAnswer":"raise a concern","explanation":"«raise a concern» — «выразить обеспокоенность»."}],"durationMinutes":8}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000035,'quizzes','{"id":760200000000035,"title":"C1 · Разговорный · Знакомство и этикет · Quiz 35","description":"C1: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":40,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «convey a subtle distinction».","options":["модерировать обсуждение","передать тонкое различие","сформулировать вопрос нейтрально","оспорить предположение"],"correctAnswer":"передать тонкое различие","explanation":"«convey a subtle distinction» — «передать тонкое различие»."},{"id":2,"question":"Какое выражение на британском английском соответствует «развернуть мысль»?","options":["qualify a statement","convey a subtle distinction","build common ground","elaborate on a point"],"correctAnswer":"elaborate on a point","explanation":"«elaborate on a point» — «развернуть мысль»."},{"id":3,"question":"Выбери точное русское значение выражения «acknowledge a counterargument».","options":["развернуть мысль","признать контраргумент","модерировать обсуждение","признать обоснованность довода"],"correctAnswer":"признать контраргумент","explanation":"«acknowledge a counterargument» — «признать контраргумент»."},{"id":4,"question":"Выбери точное русское значение выражения «adapt the register».","options":["оспорить предположение","модерировать обсуждение","подобрать стиль общения","сформулировать вопрос нейтрально"],"correctAnswer":"подобрать стиль общения","explanation":"«adapt the register» — «подобрать стиль общения»."},{"id":5,"question":"Какое выражение на британском английском соответствует «выражаться точно»?","options":["frame a question neutrally","speak with precision","moderate a discussion","challenge an assumption"],"correctAnswer":"speak with precision","explanation":"«speak with precision» — «выражаться точно»."},{"id":6,"question":"Выбери точное русское значение выражения «build common ground».","options":["оспорить предположение","найти точки соприкосновения","передать тонкое различие","сформулировать вопрос нейтрально"],"correctAnswer":"найти точки соприкосновения","explanation":"«build common ground» — «найти точки соприкосновения»."},{"id":7,"question":"Выбери точное русское значение выражения «moderate a discussion».","options":["выражаться точно","сформулировать вопрос нейтрально","найти точки соприкосновения","модерировать обсуждение"],"correctAnswer":"модерировать обсуждение","explanation":"«moderate a discussion» — «модерировать обсуждение»."},{"id":8,"question":"Какое выражение на британском английском соответствует «сформулировать вопрос нейтрально»?","options":["frame a question neutrally","speak with precision","acknowledge a counterargument","qualify a statement"],"correctAnswer":"frame a question neutrally","explanation":"«frame a question neutrally» — «сформулировать вопрос нейтрально»."}],"durationMinutes":9}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000036,'quizzes','{"id":760200000000036,"title":"C2 · Разговорный · Знакомство и этикет · Quiz 36","description":"C2: знакомство и этикет. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"📝","xp":48,"category":"Знакомство и этикет","track":"Разговорный","topic":"Знакомство и этикет","duration":"10 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «avoid unwarranted certainty».","options":["сформулировать оговорку","избегать необоснованной уверенности","сохранять риторическую сдержанность","согласовать разные точки зрения"],"correctAnswer":"избегать необоснованной уверенности","explanation":"«avoid unwarranted certainty» — «избегать необоснованной уверенности»."},{"id":2,"question":"Какое выражение на британском английском соответствует «предложить ответ с оговорками»?","options":["reconcile competing perspectives","make a nuanced distinction","invite a qualified response","foreground the implications"],"correctAnswer":"invite a qualified response","explanation":"«invite a qualified response» — «предложить ответ с оговорками»."},{"id":3,"question":"Выбери точное русское значение выражения «articulate a caveat».","options":["синтезировать противоположные взгляды","сформулировать оговорку","предложить ответ с оговорками","прийти к взвешенному суждению"],"correctAnswer":"сформулировать оговорку","explanation":"«articulate a caveat» — «сформулировать оговорку»."},{"id":4,"question":"Выбери точное русское значение выражения «synthesise opposing views».","options":["синтезировать противоположные взгляды","разграничить намерение и результат","сохранять риторическую сдержанность","выявить ложную дихотомию"],"correctAnswer":"синтезировать противоположные взгляды","explanation":"«synthesise opposing views» — «синтезировать противоположные взгляды»."},{"id":5,"question":"Какое выражение на британском английском соответствует «согласовать разные точки зрения»?","options":["synthesise opposing views","reach a considered judgement","reconcile competing perspectives","avoid unwarranted certainty"],"correctAnswer":"reconcile competing perspectives","explanation":"«reconcile competing perspectives» — «согласовать разные точки зрения»."},{"id":6,"question":"Выбери точное русское значение выражения «make a nuanced distinction».","options":["согласовать разные точки зрения","провести тонкое различие","сохранять риторическую сдержанность","оспорить исходную предпосылку"],"correctAnswer":"провести тонкое различие","explanation":"«make a nuanced distinction» — «провести тонкое различие»."},{"id":7,"question":"Выбери точное русское значение выражения «maintain rhetorical restraint».","options":["синтезировать противоположные взгляды","согласовать разные точки зрения","сохранять риторическую сдержанность","выявить ложную дихотомию"],"correctAnswer":"сохранять риторическую сдержанность","explanation":"«maintain rhetorical restraint» — «сохранять риторическую сдержанность»."},{"id":8,"question":"Какое выражение на британском английском соответствует «оспорить исходную предпосылку»?","options":["avoid unwarranted certainty","synthesise opposing views","challenge the underlying premise","reach a considered judgement"],"correctAnswer":"challenge the underlying premise","explanation":"«challenge the underlying premise» — «оспорить исходную предпосылку»."}],"durationMinutes":10}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
