INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000038,'quizzes','{"id":760200000000038,"title":"A2 · Разговорный · Повседневные ситуации · Quiz 38","description":"A2: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"📝","xp":25,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"6 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «I would like».","options":["не торопись","что ты думаешь?","я бы хотел","дай мне знать"],"correctAnswer":"я бы хотел","explanation":"«I would like» — «я бы хотел»."},{"id":2,"question":"Какое выражение на британском английском соответствует «кстати»?","options":["by the way","could I have","let me know","take your time"],"correctAnswer":"by the way","explanation":"«by the way» — «кстати»."},{"id":3,"question":"Выбери точное русское значение выражения «I disagree».","options":["что ты думаешь?","кстати","я не уверен","я не согласен"],"correctAnswer":"я не согласен","explanation":"«I disagree» — «я не согласен»."},{"id":4,"question":"Выбери точное русское значение выражения «take your time».","options":["можно мне","я ищу","не торопись","кстати"],"correctAnswer":"не торопись","explanation":"«take your time» — «не торопись»."},{"id":5,"question":"Какое выражение на британском английском соответствует «это зависит от обстоятельств»?","options":["I disagree","take your time","it depends","I agree"],"correctAnswer":"it depends","explanation":"«it depends» — «это зависит от обстоятельств»."},{"id":6,"question":"Выбери точное русское значение выражения «could I have».","options":["дай мне знать","я не уверен","можно мне","что ты думаешь?"],"correctAnswer":"можно мне","explanation":"«could I have» — «можно мне»."},{"id":7,"question":"Выбери точное русское значение выражения «what do you think?».","options":["можно мне","я согласен","что ты думаешь?","дай мне знать"],"correctAnswer":"что ты думаешь?","explanation":"«what do you think?» — «что ты думаешь?»."},{"id":8,"question":"Какое выражение на британском английском соответствует «я согласен»?","options":["by the way","I disagree","I agree","I am not sure"],"correctAnswer":"I agree","explanation":"«I agree» — «я согласен»."}],"durationMinutes":6}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000039,'quizzes','{"id":760200000000039,"title":"B1 · Разговорный · Повседневные ситуации · Quiz 39","description":"B1: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"📝","xp":30,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"7 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «make a suggestion».","options":["с нетерпением ждать","принимать участие в","предложить идею","это звучит разумно"],"correctAnswer":"предложить идею","explanation":"«make a suggestion» — «предложить идею»."},{"id":2,"question":"Какое выражение на британском английском соответствует «если честно»?","options":["look forward to","to be honest","take part in","in my opinion"],"correctAnswer":"to be honest","explanation":"«to be honest» — «если честно»."},{"id":3,"question":"Выбери точное русское значение выражения «as far as I know».","options":["я понимаю твою точку зрения","если честно","достичь соглашения","насколько мне известно"],"correctAnswer":"насколько мне известно","explanation":"«as far as I know» — «насколько мне известно»."},{"id":4,"question":"Выбери точное русское значение выражения «look forward to».","options":["это звучит разумно","с нетерпением ждать","я понимаю твою точку зрения","по моему мнению"],"correctAnswer":"с нетерпением ждать","explanation":"«look forward to» — «с нетерпением ждать»."},{"id":5,"question":"Какое выражение на британском английском соответствует «достичь соглашения»?","options":["as far as I know","reach an agreement","clear up a misunderstanding","to be honest"],"correctAnswer":"reach an agreement","explanation":"«reach an agreement» — «достичь соглашения»."},{"id":6,"question":"Выбери точное русское значение выражения «clear up a misunderstanding».","options":["прояснить недоразумение","принимать участие в","я понимаю твою точку зрения","это звучит разумно"],"correctAnswer":"прояснить недоразумение","explanation":"«clear up a misunderstanding» — «прояснить недоразумение»."},{"id":7,"question":"Выбери точное русское значение выражения «take part in».","options":["это звучит разумно","насколько мне известно","с другой стороны","принимать участие в"],"correctAnswer":"принимать участие в","explanation":"«take part in» — «принимать участие в»."},{"id":8,"question":"Какое выражение на британском английском соответствует «это звучит разумно»?","options":["in my opinion","on the other hand","look forward to","that sounds reasonable"],"correctAnswer":"that sounds reasonable","explanation":"«that sounds reasonable» — «это звучит разумно»."}],"durationMinutes":7}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000040,'quizzes','{"id":760200000000040,"title":"B2 · Разговорный · Повседневные ситуации · Quiz 40","description":"B2: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"📝","xp":35,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"8 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «clarify an assumption».","options":["взвесить варианты","прояснить предположение","привести веский аргумент","разобраться с недопониманием"],"correctAnswer":"прояснить предположение","explanation":"«clarify an assumption» — «прояснить предположение»."},{"id":2,"question":"Какое выражение на британском английском соответствует «выразить иначе»?","options":["clarify an assumption","strike a balance","put it another way","weigh up the options"],"correctAnswer":"put it another way","explanation":"«put it another way» — «выразить иначе»."},{"id":3,"question":"Выбери точное русское значение выражения «come to a conclusion».","options":["выразить иначе","испытывать смешанные чувства","взвесить варианты","прийти к выводу"],"correctAnswer":"прийти к выводу","explanation":"«come to a conclusion» — «прийти к выводу»."},{"id":4,"question":"Выбери точное русское значение выражения «raise a concern».","options":["выразить сомнение","выразить обеспокоенность","прийти к выводу","испытывать смешанные чувства"],"correctAnswer":"выразить обеспокоенность","explanation":"«raise a concern» — «выразить обеспокоенность»."},{"id":5,"question":"Какое выражение на британском английском соответствует «найти баланс»?","options":["strike a balance","have mixed feelings","address a misunderstanding","put it another way"],"correctAnswer":"strike a balance","explanation":"«strike a balance» — «найти баланс»."},{"id":6,"question":"Выбери точное русское значение выражения «take into account».","options":["привести веский аргумент","выразить иначе","принять во внимание","прояснить предположение"],"correctAnswer":"принять во внимание","explanation":"«take into account» — «принять во внимание»."},{"id":7,"question":"Выбери точное русское значение выражения «address a misunderstanding».","options":["взвесить варианты","найти баланс","испытывать смешанные чувства","разобраться с недопониманием"],"correctAnswer":"разобраться с недопониманием","explanation":"«address a misunderstanding» — «разобраться с недопониманием»."},{"id":8,"question":"Какое выражение на британском английском соответствует «ответить тактично»?","options":["come to a conclusion","respond tactfully","clarify an assumption","express a reservation"],"correctAnswer":"respond tactfully","explanation":"«respond tactfully» — «ответить тактично»."}],"durationMinutes":8}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000041,'quizzes','{"id":760200000000041,"title":"C1 · Разговорный · Повседневные ситуации · Quiz 41","description":"C1: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":43,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «acknowledge a counterargument».","options":["уточнить оговорками утверждение","признать обоснованность довода","выражаться точно","признать контраргумент"],"correctAnswer":"признать контраргумент","explanation":"«acknowledge a counterargument» — «признать контраргумент»."},{"id":2,"question":"Какое выражение на британском английском соответствует «передать тонкое различие»?","options":["adapt the register","concede a point","convey a subtle distinction","elaborate on a point"],"correctAnswer":"convey a subtle distinction","explanation":"«convey a subtle distinction» — «передать тонкое различие»."},{"id":3,"question":"Выбери точное русское значение выражения «speak with precision».","options":["модерировать обсуждение","развернуть мысль","признать контраргумент","выражаться точно"],"correctAnswer":"выражаться точно","explanation":"«speak with precision» — «выражаться точно»."},{"id":4,"question":"Выбери точное русское значение выражения «draw an inference».","options":["сделать вывод","признать контраргумент","найти точки соприкосновения","уточнить оговорками утверждение"],"correctAnswer":"сделать вывод","explanation":"«draw an inference» — «сделать вывод»."},{"id":5,"question":"Какое выражение на британском английском соответствует «оспорить предположение»?","options":["qualify a statement","challenge an assumption","elaborate on a point","draw an inference"],"correctAnswer":"challenge an assumption","explanation":"«challenge an assumption» — «оспорить предположение»."},{"id":6,"question":"Выбери точное русское значение выражения «concede a point».","options":["признать обоснованность довода","модерировать обсуждение","сделать вывод","сформулировать вопрос нейтрально"],"correctAnswer":"признать обоснованность довода","explanation":"«concede a point» — «признать обоснованность довода»."},{"id":7,"question":"Выбери точное русское значение выражения «build common ground».","options":["развернуть мысль","модерировать обсуждение","признать обоснованность довода","найти точки соприкосновения"],"correctAnswer":"найти точки соприкосновения","explanation":"«build common ground» — «найти точки соприкосновения»."},{"id":8,"question":"Какое выражение на британском английском соответствует «уточнить оговорками утверждение»?","options":["qualify a statement","acknowledge a counterargument","concede a point","adapt the register"],"correctAnswer":"qualify a statement","explanation":"«qualify a statement» — «уточнить оговорками утверждение»."}],"durationMinutes":9}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000042,'quizzes','{"id":760200000000042,"title":"C2 · Разговорный · Повседневные ситуации · Quiz 42","description":"C2: повседневные ситуации. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"📝","xp":45,"category":"Повседневные ситуации","track":"Разговорный","topic":"Повседневные ситуации","duration":"10 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «make a nuanced distinction».","options":["сформулировать оговорку","оспорить исходную предпосылку","избегать необоснованной уверенности","провести тонкое различие"],"correctAnswer":"провести тонкое различие","explanation":"«make a nuanced distinction» — «провести тонкое различие»."},{"id":2,"question":"Какое выражение на британском английском соответствует «сформулировать оговорку»?","options":["synthesise opposing views","reconcile competing perspectives","articulate a caveat","make a nuanced distinction"],"correctAnswer":"articulate a caveat","explanation":"«articulate a caveat» — «сформулировать оговорку»."},{"id":3,"question":"Выбери точное русское значение выражения «challenge the underlying premise».","options":["разграничить намерение и результат","оспорить исходную предпосылку","выдвинуть на первый план последствия","согласовать разные точки зрения"],"correctAnswer":"оспорить исходную предпосылку","explanation":"«challenge the underlying premise» — «оспорить исходную предпосылку»."},{"id":4,"question":"Выбери точное русское значение выражения «avoid unwarranted certainty».","options":["провести тонкое различие","сформулировать оговорку","синтезировать противоположные взгляды","избегать необоснованной уверенности"],"correctAnswer":"избегать необоснованной уверенности","explanation":"«avoid unwarranted certainty» — «избегать необоснованной уверенности»."},{"id":5,"question":"Какое выражение на британском английском соответствует «сохранять риторическую сдержанность»?","options":["challenge the underlying premise","reach a considered judgement","foreground the implications","maintain rhetorical restraint"],"correctAnswer":"maintain rhetorical restraint","explanation":"«maintain rhetorical restraint» — «сохранять риторическую сдержанность»."},{"id":6,"question":"Выбери точное русское значение выражения «foreground the implications».","options":["выдвинуть на первый план последствия","прийти к взвешенному суждению","сохранять риторическую сдержанность","разграничить намерение и результат"],"correctAnswer":"выдвинуть на первый план последствия","explanation":"«foreground the implications» — «выдвинуть на первый план последствия»."},{"id":7,"question":"Выбери точное русское значение выражения «invite a qualified response».","options":["выдвинуть на первый план последствия","выявить ложную дихотомию","сохранять риторическую сдержанность","предложить ответ с оговорками"],"correctAnswer":"предложить ответ с оговорками","explanation":"«invite a qualified response» — «предложить ответ с оговорками»."},{"id":8,"question":"Какое выражение на британском английском соответствует «согласовать разные точки зрения»?","options":["reconcile competing perspectives","articulate a caveat","maintain rhetorical restraint","synthesise opposing views"],"correctAnswer":"reconcile competing perspectives","explanation":"«reconcile competing perspectives» — «согласовать разные точки зрения»."}],"durationMinutes":10}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000043,'quizzes','{"id":760200000000043,"title":"A1 · Разговорный · Мнение и общение · Quiz 43","description":"A1: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A1","icon":"📝","xp":20,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"5 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «good morning».","options":["спасибо","доброе утро","мне жаль","не могли бы вы мне помочь?"],"correctAnswer":"доброе утро","explanation":"«good morning» — «доброе утро»."},{"id":2,"question":"Какое выражение на британском английском соответствует «меня зовут»?","options":["nice to meet you","see you later","my name is","could you help me?"],"correctAnswer":"my name is","explanation":"«my name is» — «меня зовут»."},{"id":3,"question":"Выбери точное русское значение выражения «excuse me».","options":["меня зовут","мне жаль","извините","добрый вечер"],"correctAnswer":"извините","explanation":"«excuse me» — «извините»."},{"id":4,"question":"Выбери точное русское значение выражения «see you later».","options":["добрый вечер","спасибо","увидимся позже","привет"],"correctAnswer":"увидимся позже","explanation":"«see you later» — «увидимся позже»."},{"id":5,"question":"Какое выражение на британском английском соответствует «мне жаль»?","options":["could you help me?","how are you?","I am sorry","good morning"],"correctAnswer":"I am sorry","explanation":"«I am sorry» — «мне жаль»."},{"id":6,"question":"Выбери точное русское значение выражения «could you help me?».","options":["не могли бы вы мне помочь?","приятно познакомиться","извините","меня зовут"],"correctAnswer":"не могли бы вы мне помочь?","explanation":"«could you help me?» — «не могли бы вы мне помочь?»."},{"id":7,"question":"Выбери точное русское значение выражения «how are you?».","options":["приятно познакомиться","как дела?","меня зовут","спасибо"],"correctAnswer":"как дела?","explanation":"«how are you?» — «как дела?»."},{"id":8,"question":"Какое выражение на британском английском соответствует «добрый вечер»?","options":["please","could you help me?","good evening","my name is"],"correctAnswer":"good evening","explanation":"«good evening» — «добрый вечер»."}],"durationMinutes":5}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000044,'quizzes','{"id":760200000000044,"title":"A2 · Разговорный · Мнение и общение · Quiz 44","description":"A2: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"📝","xp":25,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"6 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «let me know».","options":["дай мне знать","я не уверен","не торопись","я не согласен"],"correctAnswer":"дай мне знать","explanation":"«let me know» — «дай мне знать»."},{"id":2,"question":"Какое выражение на британском английском соответствует «это зависит от обстоятельств»?","options":["let me know","it depends","I disagree","I would like"],"correctAnswer":"it depends","explanation":"«it depends» — «это зависит от обстоятельств»."},{"id":3,"question":"Выбери точное русское значение выражения «I disagree».","options":["я бы хотел","я не уверен","я не согласен","начнём?"],"correctAnswer":"я не согласен","explanation":"«I disagree» — «я не согласен»."},{"id":4,"question":"Выбери точное русское значение выражения «could I have».","options":["я не уверен","я не согласен","можно мне","это зависит от обстоятельств"],"correctAnswer":"можно мне","explanation":"«could I have» — «можно мне»."},{"id":5,"question":"Какое выражение на британском английском соответствует «я согласен»?","options":["I am looking for","I agree","it depends","I disagree"],"correctAnswer":"I agree","explanation":"«I agree» — «я согласен»."},{"id":6,"question":"Выбери точное русское значение выражения «what do you think?».","options":["это зависит от обстоятельств","можно мне","кстати","что ты думаешь?"],"correctAnswer":"что ты думаешь?","explanation":"«what do you think?» — «что ты думаешь?»."},{"id":7,"question":"Выбери точное русское значение выражения «take your time».","options":["это зависит от обстоятельств","я не уверен","не торопись","начнём?"],"correctAnswer":"не торопись","explanation":"«take your time» — «не торопись»."},{"id":8,"question":"Какое выражение на британском английском соответствует «я ищу»?","options":["by the way","I am looking for","take your time","could I have"],"correctAnswer":"I am looking for","explanation":"«I am looking for» — «я ищу»."}],"durationMinutes":6}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000045,'quizzes','{"id":760200000000045,"title":"B1 · Разговорный · Мнение и общение · Quiz 45","description":"B1: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B1","icon":"📝","xp":30,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"7 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «reach an agreement».","options":["это звучит разумно","если честно","насколько мне известно","достичь соглашения"],"correctAnswer":"достичь соглашения","explanation":"«reach an agreement» — «достичь соглашения»."},{"id":2,"question":"Какое выражение на британском английском соответствует «это звучит разумно»?","options":["look forward to","to be honest","on the other hand","that sounds reasonable"],"correctAnswer":"that sounds reasonable","explanation":"«that sounds reasonable» — «это звучит разумно»."},{"id":3,"question":"Выбери точное русское значение выражения «look forward to».","options":["с нетерпением ждать","я понимаю твою точку зрения","принимать участие в","если честно"],"correctAnswer":"с нетерпением ждать","explanation":"«look forward to» — «с нетерпением ждать»."},{"id":4,"question":"Выбери точное русское значение выражения «to be honest».","options":["поддерживать связь","если честно","по моему мнению","насколько мне известно"],"correctAnswer":"если честно","explanation":"«to be honest» — «если честно»."},{"id":5,"question":"Какое выражение на британском английском соответствует «поддерживать связь»?","options":["keep in touch","I see your point","that sounds reasonable","reach an agreement"],"correctAnswer":"keep in touch","explanation":"«keep in touch» — «поддерживать связь»."},{"id":6,"question":"Выбери точное русское значение выражения «take part in».","options":["это звучит разумно","если честно","принимать участие в","насколько мне известно"],"correctAnswer":"принимать участие в","explanation":"«take part in» — «принимать участие в»."},{"id":7,"question":"Выбери точное русское значение выражения «clear up a misunderstanding».","options":["прояснить недоразумение","с другой стороны","по моему мнению","с нетерпением ждать"],"correctAnswer":"прояснить недоразумение","explanation":"«clear up a misunderstanding» — «прояснить недоразумение»."},{"id":8,"question":"Какое выражение на британском английском соответствует «с другой стороны»?","options":["in my opinion","take part in","clear up a misunderstanding","on the other hand"],"correctAnswer":"on the other hand","explanation":"«on the other hand» — «с другой стороны»."}],"durationMinutes":7}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000046,'quizzes','{"id":760200000000046,"title":"B2 · Разговорный · Мнение и общение · Quiz 46","description":"B2: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"B2","icon":"📝","xp":38,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"8 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «clarify an assumption».","options":["выразить сомнение","выразить обеспокоенность","найти баланс","прояснить предположение"],"correctAnswer":"прояснить предположение","explanation":"«clarify an assumption» — «прояснить предположение»."},{"id":2,"question":"Какое выражение на британском английском соответствует «найти баланс»?","options":["strike a balance","make a valid point","raise a concern","respond tactfully"],"correctAnswer":"strike a balance","explanation":"«strike a balance» — «найти баланс»."},{"id":3,"question":"Выбери точное русское значение выражения «come to a conclusion».","options":["выразить сомнение","найти баланс","прийти к выводу","принять во внимание"],"correctAnswer":"прийти к выводу","explanation":"«come to a conclusion» — «прийти к выводу»."},{"id":4,"question":"Выбери точное русское значение выражения «put it another way».","options":["выразить иначе","привести веский аргумент","ответить тактично","разобраться с недопониманием"],"correctAnswer":"выразить иначе","explanation":"«put it another way» — «выразить иначе»."},{"id":5,"question":"Какое выражение на британском английском соответствует «принять во внимание»?","options":["raise a concern","take into account","come to a conclusion","make a valid point"],"correctAnswer":"take into account","explanation":"«take into account» — «принять во внимание»."},{"id":6,"question":"Выбери точное русское значение выражения «raise a concern».","options":["выразить обеспокоенность","прийти к выводу","взвесить варианты","выразить иначе"],"correctAnswer":"выразить обеспокоенность","explanation":"«raise a concern» — «выразить обеспокоенность»."},{"id":7,"question":"Выбери точное русское значение выражения «weigh up the options».","options":["взвесить варианты","выразить иначе","привести веский аргумент","разобраться с недопониманием"],"correctAnswer":"взвесить варианты","explanation":"«weigh up the options» — «взвесить варианты»."},{"id":8,"question":"Какое выражение на британском английском соответствует «ответить тактично»?","options":["weigh up the options","take into account","respond tactfully","make a valid point"],"correctAnswer":"respond tactfully","explanation":"«respond tactfully» — «ответить тактично»."}],"durationMinutes":8}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000047,'quizzes','{"id":760200000000047,"title":"C1 · Разговорный · Мнение и общение · Quiz 47","description":"C1: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C1","icon":"📝","xp":40,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"9 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «adapt the register».","options":["сформулировать вопрос нейтрально","подобрать стиль общения","уточнить оговорками утверждение","признать обоснованность довода"],"correctAnswer":"подобрать стиль общения","explanation":"«adapt the register» — «подобрать стиль общения»."},{"id":2,"question":"Какое выражение на британском английском соответствует «признать обоснованность довода»?","options":["concede a point","frame a question neutrally","adapt the register","challenge an assumption"],"correctAnswer":"concede a point","explanation":"«concede a point» — «признать обоснованность довода»."},{"id":3,"question":"Выбери точное русское значение выражения «elaborate on a point».","options":["признать контраргумент","признать обоснованность довода","оспорить предположение","развернуть мысль"],"correctAnswer":"развернуть мысль","explanation":"«elaborate on a point» — «развернуть мысль»."},{"id":4,"question":"Выбери точное русское значение выражения «frame a question neutrally».","options":["развернуть мысль","оспорить предположение","сделать вывод","сформулировать вопрос нейтрально"],"correctAnswer":"сформулировать вопрос нейтрально","explanation":"«frame a question neutrally» — «сформулировать вопрос нейтрально»."},{"id":5,"question":"Какое выражение на британском английском соответствует «признать контраргумент»?","options":["acknowledge a counterargument","convey a subtle distinction","concede a point","moderate a discussion"],"correctAnswer":"acknowledge a counterargument","explanation":"«acknowledge a counterargument» — «признать контраргумент»."},{"id":6,"question":"Выбери точное русское значение выражения «challenge an assumption».","options":["развернуть мысль","передать тонкое различие","модерировать обсуждение","оспорить предположение"],"correctAnswer":"оспорить предположение","explanation":"«challenge an assumption» — «оспорить предположение»."},{"id":7,"question":"Выбери точное русское значение выражения «qualify a statement».","options":["уточнить оговорками утверждение","сделать вывод","оспорить предположение","модерировать обсуждение"],"correctAnswer":"уточнить оговорками утверждение","explanation":"«qualify a statement» — «уточнить оговорками утверждение»."},{"id":8,"question":"Какое выражение на британском английском соответствует «выражаться точно»?","options":["concede a point","elaborate on a point","moderate a discussion","speak with precision"],"correctAnswer":"speak with precision","explanation":"«speak with precision» — «выражаться точно»."}],"durationMinutes":9}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000048,'quizzes','{"id":760200000000048,"title":"C2 · Разговорный · Мнение и общение · Quiz 48","description":"C2: мнение и общение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"C2","icon":"📝","xp":45,"category":"Мнение и общение","track":"Разговорный","topic":"Мнение и общение","duration":"10 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «invite a qualified response».","options":["прийти к взвешенному суждению","предложить ответ с оговорками","разграничить намерение и результат","избегать необоснованной уверенности"],"correctAnswer":"предложить ответ с оговорками","explanation":"«invite a qualified response» — «предложить ответ с оговорками»."},{"id":2,"question":"Какое выражение на британском английском соответствует «разграничить намерение и результат»?","options":["expose a false dichotomy","articulate a caveat","synthesise opposing views","distinguish intent from impact"],"correctAnswer":"distinguish intent from impact","explanation":"«distinguish intent from impact» — «разграничить намерение и результат»."},{"id":3,"question":"Выбери точное русское значение выражения «reconcile competing perspectives».","options":["согласовать разные точки зрения","сформулировать оговорку","синтезировать противоположные взгляды","разграничить намерение и результат"],"correctAnswer":"согласовать разные точки зрения","explanation":"«reconcile competing perspectives» — «согласовать разные точки зрения»."},{"id":4,"question":"Выбери точное русское значение выражения «challenge the underlying premise».","options":["оспорить исходную предпосылку","сохранять риторическую сдержанность","предложить ответ с оговорками","выдвинуть на первый план последствия"],"correctAnswer":"оспорить исходную предпосылку","explanation":"«challenge the underlying premise» — «оспорить исходную предпосылку»."},{"id":5,"question":"Какое выражение на британском английском соответствует «избегать необоснованной уверенности»?","options":["challenge the underlying premise","make a nuanced distinction","avoid unwarranted certainty","reconcile competing perspectives"],"correctAnswer":"avoid unwarranted certainty","explanation":"«avoid unwarranted certainty» — «избегать необоснованной уверенности»."},{"id":6,"question":"Выбери точное русское значение выражения «expose a false dichotomy».","options":["оспорить исходную предпосылку","синтезировать противоположные взгляды","выявить ложную дихотомию","согласовать разные точки зрения"],"correctAnswer":"выявить ложную дихотомию","explanation":"«expose a false dichotomy» — «выявить ложную дихотомию»."},{"id":7,"question":"Выбери точное русское значение выражения «foreground the implications».","options":["разграничить намерение и результат","сохранять риторическую сдержанность","выдвинуть на первый план последствия","согласовать разные точки зрения"],"correctAnswer":"выдвинуть на первый план последствия","explanation":"«foreground the implications» — «выдвинуть на первый план последствия»."},{"id":8,"question":"Какое выражение на британском английском соответствует «прийти к взвешенному суждению»?","options":["reach a considered judgement","challenge the underlying premise","reconcile competing perspectives","synthesise opposing views"],"correctAnswer":"reach a considered judgement","explanation":"«reach a considered judgement» — «прийти к взвешенному суждению»."}],"durationMinutes":10}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000049,'quizzes','{"id":760200000000049,"title":"A1 · Разговорный · Диалог и уточнение · Quiz 49","description":"A1: диалог и уточнение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A1","icon":"📝","xp":20,"category":"Диалог и уточнение","track":"Разговорный","topic":"Диалог и уточнение","duration":"5 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «thank you».","options":["меня зовут","как дела?","не могли бы вы мне помочь?","спасибо"],"correctAnswer":"спасибо","explanation":"«thank you» — «спасибо»."},{"id":2,"question":"Какое выражение на британском английском соответствует «извините»?","options":["how are you?","please","excuse me","thank you"],"correctAnswer":"excuse me","explanation":"«excuse me» — «извините»."},{"id":3,"question":"Выбери точное русское значение выражения «see you later».","options":["увидимся позже","меня зовут","приятно познакомиться","извините"],"correctAnswer":"увидимся позже","explanation":"«see you later» — «увидимся позже»."},{"id":4,"question":"Выбери точное русское значение выражения «I am sorry».","options":["увидимся позже","не могли бы вы мне помочь?","мне жаль","пожалуйста"],"correctAnswer":"мне жаль","explanation":"«I am sorry» — «мне жаль»."},{"id":5,"question":"Какое выражение на британском английском соответствует «не могли бы вы мне помочь?»?","options":["thank you","please","good morning","could you help me?"],"correctAnswer":"could you help me?","explanation":"«could you help me?» — «не могли бы вы мне помочь?»."},{"id":6,"question":"Выбери точное русское значение выражения «hello».","options":["меня зовут","пожалуйста","привет","извините"],"correctAnswer":"привет","explanation":"«hello» — «привет»."},{"id":7,"question":"Выбери точное русское значение выражения «my name is».","options":["увидимся позже","пожалуйста","доброе утро","меня зовут"],"correctAnswer":"меня зовут","explanation":"«my name is» — «меня зовут»."},{"id":8,"question":"Какое выражение на британском английском соответствует «пожалуйста»?","options":["could you help me?","please","how are you?","hello"],"correctAnswer":"please","explanation":"«please» — «пожалуйста»."}],"durationMinutes":5}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO content(id,section,data,updated_at) VALUES (760200000000050,'quizzes','{"id":760200000000050,"title":"A2 · Разговорный · Диалог и уточнение · Quiz 50","description":"A2: диалог и уточнение. 8 заданий на точное понимание и употребление британского английского.","status":"published","level":"A2","icon":"📝","xp":25,"category":"Диалог и уточнение","track":"Разговорный","topic":"Диалог и уточнение","duration":"6 мин","section":"quizzes","payload":{"questions":[{"id":1,"question":"Выбери точное русское значение выражения «I disagree».","options":["я не согласен","дай мне знать","не торопись","я согласен"],"correctAnswer":"я не согласен","explanation":"«I disagree» — «я не согласен»."},{"id":2,"question":"Какое выражение на британском английском соответствует «можно мне»?","options":["could I have","take your time","I would like","I am not sure"],"correctAnswer":"could I have","explanation":"«could I have» — «можно мне»."},{"id":3,"question":"Выбери точное русское значение выражения «I agree».","options":["дай мне знать","я бы хотел","что ты думаешь?","я согласен"],"correctAnswer":"я согласен","explanation":"«I agree» — «я согласен»."},{"id":4,"question":"Выбери точное русское значение выражения «shall we start?».","options":["я бы хотел","я согласен","начнём?","можно мне"],"correctAnswer":"начнём?","explanation":"«shall we start?» — «начнём?»."},{"id":5,"question":"Какое выражение на британском английском соответствует «не торопись»?","options":["take your time","could I have","by the way","what do you think?"],"correctAnswer":"take your time","explanation":"«take your time» — «не торопись»."},{"id":6,"question":"Выбери точное русское значение выражения «I am not sure».","options":["кстати","я не уверен","я ищу","начнём?"],"correctAnswer":"я не уверен","explanation":"«I am not sure» — «я не уверен»."},{"id":7,"question":"Выбери точное русское значение выражения «by the way».","options":["не торопись","я ищу","дай мне знать","кстати"],"correctAnswer":"кстати","explanation":"«by the way» — «кстати»."},{"id":8,"question":"Какое выражение на британском английском соответствует «это зависит от обстоятельств»?","options":["could I have","I would like","it depends","I agree"],"correctAnswer":"it depends","explanation":"«it depends» — «это зависит от обстоятельств»."}],"durationMinutes":6}}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
